mission_data:
  TSN Command Systems Version {{ g.version }}, compiled at {{ g.time }}. Systems:{% for system in g.data.get("systems", []) %} {{ system }}{% endfor %} - Extensions:{% for script in g.data.get("extensions", []) %} {{ script }}{% endfor %}
{% set ShuttleList = ["Proteus", "Theseus", "Odysseus", "Perseus", "Dionysus", "Icarus", "Adonis", "Invention"] %}
{% include 'Start Up.xml' %}
{% include 'Elements.xml' %}
{% include 'Comms.xml' %}
{% include 'Custom Config.xml' %}
{% import 'ModuleUtils.xml' as modutil %}
{% import 'Utils.xml' as util %}
{% for ship in util.shipConfigs %}
  {% for module in g.data.get("modules", {}).get("ship" + ship.id, []) %}
      {% import 'Modules/' + module + '.xml' as mod %}
      {{ mod.render(ship, modutil) }}
  {% endfor %}
{% endfor %}
{% for system in g.data.get("systems", []) %}
  {% include 'Systems (Generated)/' + system + '.xml' %}
{% endfor %}
{% for extension in g.data.get("extensions", []) %}
  {% include 'Extensions/' + extension + '.xml' %}
{% endfor %}
{% include 'GM Console.xml' %}
